def create_domain():
    # --- domain (method: BathymetryFile) ---
    with netCDF4.Dataset(resolve_data_path('${BATHYMETRY_FOLDER}/bathymetry_nse.nc')) as nc:
        nc.set_auto_mask(False)
        H = nc['depth_rx0_0p20'][...]
        mask = nc['ocean_mask'][...]
        lon = nc['lon'][:]
        lat = nc['lat'][:]
    domain = pygetm.domain.create_spherical(
        lon=lon, lat=lat, H=H, mask=mask,
        z0=0.01,
    )

    # --- open_boundaries ---
    domain.open_boundaries.add_by_index(
        side=pygetm.open_boundaries.Side.LEFT,
        l=0,
        mstart=0,
        mstop=73,
        type_2d=-4,  # FLATHER_TRANSPORT
        type_3d=1,  # ZERO_GRADIENT
    )
    domain.open_boundaries.add_by_index(
        side=pygetm.open_boundaries.Side.LEFT,
        l=0,
        mstart=137,
        mstop=169,
        type_2d=-4,  # FLATHER_TRANSPORT
        type_3d=1,  # ZERO_GRADIENT
    )
    domain.open_boundaries.add_by_index(
        side=pygetm.open_boundaries.Side.LEFT,
        l=16,
        mstart=201,
        mstop=214,
        type_2d=-4,  # FLATHER_TRANSPORT
        type_3d=1,  # ZERO_GRADIENT
    )
    domain.open_boundaries.add_by_index(
        side=pygetm.open_boundaries.Side.LEFT,
        l=36,
        mstart=214,
        mstop=227,
        type_2d=-4,  # FLATHER_TRANSPORT
        type_3d=1,  # ZERO_GRADIENT
    )
    domain.open_boundaries.add_by_index(
        side=pygetm.open_boundaries.Side.TOP,
        l=213,
        mstart=17,
        mstop=36,
        type_2d=-4,  # FLATHER_TRANSPORT
        type_3d=1,  # ZERO_GRADIENT
    )
    domain.open_boundaries.add_by_index(
        side=pygetm.open_boundaries.Side.TOP,
        l=226,
        mstart=37,
        mstop=77,
        type_2d=-4,  # FLATHER_TRANSPORT
        type_3d=1,  # ZERO_GRADIENT
    )
    domain.open_boundaries.add_by_index(
        side=pygetm.open_boundaries.Side.TOP,
        l=246,
        mstart=84,
        mstop=154,
        type_2d=-4,  # FLATHER_TRANSPORT
        type_3d=1,  # ZERO_GRADIENT
    )
    domain.open_boundaries.add_by_index(
        side=pygetm.open_boundaries.Side.RIGHT,
        l=256,
        mstart=120,
        mstop=136,
        type_2d=-4,  # FLATHER_TRANSPORT
        type_3d=1,  # ZERO_GRADIENT
    )
    domain.open_boundaries.add_by_index(
        side=pygetm.open_boundaries.Side.BOTTOM,
        l=0,
        mstart=1,
        mstop=35,
        type_2d=-4,  # FLATHER_TRANSPORT
        type_3d=1,  # ZERO_GRADIENT
    )

    # river_discharge.script -- see generated_nse_cmip6_raw_utils.py
    add_rivers(domain, config)

    return domain

def create_simulation(domain):
    # --- simulation ---
    internal_pressure = pygetm.internal_pressure.ShchepetkinMcwilliams(
    )
    vertical_coordinates = pygetm.vertical_coordinates.GVC(
        nz=40,
        ddl=0.75,
        ddu=0.75,
        gamma_surf=True,
        Dgamma=10.0,
    )
    airsea = pygetm.airsea.FluxesFromMeteo(
        shortwave_method=-1,  # NET_FLUX
        longwave_method=-1,  # NET_FLUX
        albedo_method=awex.AlbedoMethod.PAYNE,
        humidity_measure=awex.HumidityMeasure.SPECIFIC_HUMIDITY,
        calculate_evaporation=True,
    )
    radiation = pygetm.radiation.TwoBand(
        reflect_at_bottom=False,
    )
    momentum = pygetm.momentum.Momentum(
        Am=0.0,
        An=25.0,
        cnpar=1.0,
        advection_split_2d=pygetm.operators.AdvectionSplit.FULL,
        coriolis_scheme=pygetm.momentum.CoriolisScheme.DEFAULT,
        avmmol=1.8e-06,
    )
    # fabm=None disables FABM; a fabm.yaml path (or True for pygetm's own default
    # location) enables it -- output.files entries marked requires_fabm are then
    # requested instead of skipped. Configured here as None;
    # --fabm/--no-fabm on the command line overrides it (see -h).
    if args.fabm is False:
        fabm = None
    elif args.fabm is True:
        fabm = True
    elif args.fabm is not None:
        fabm = pathlib.Path(resolve_data_path(args.fabm))
    else:
        fabm = None

    sim = pygetm.simulation.Simulation(
        domain,
        runtype=pygetm.constants.RunType.BAROCLINIC,
        advection_scheme=pygetm.operators.AdvectionScheme.SUPERBEE,
        gotm=pathlib.Path(resolve_data_path('${GOTM_FOLDER}/gotm.yaml')),
        Dmin=0.1,
        Dcrit=0.5,
        internal_pressure=internal_pressure,
        vertical_coordinates=vertical_coordinates,
        airsea=airsea,
        radiation=radiation,
        momentum=momentum,
        fabm=fabm,
    )

    # hydrography.data_script -- see generated_nse_cmip6_raw_utils.py
    if not args.load_restart:
        set_hydrography_ic(sim, domain, config)

    # --- data_assignments ---
    sim['temp'].open_boundaries.values.set(pygetm.input.from_nc([resolve_data_path('${BOUNDARY_FOLDER_BAROCLINIC_CMIP6}/GFDL-ESM4/historical/bdy/bdy_3d_thetao_20100101_20141231_noleap.nc'), resolve_data_path('${BOUNDARY_FOLDER_BAROCLINIC_CMIP6}/GFDL-ESM4/ssp126/bdy/bdy_3d_thetao_20150101_21001231_noleap.nc')], 'thetao'), on_grid=True, climatology=False)
    sim['salt'].open_boundaries.values.set(pygetm.input.from_nc([resolve_data_path('${BOUNDARY_FOLDER_BAROCLINIC_CMIP6}/GFDL-ESM4/historical/bdy/bdy_3d_so_20100101_20141231_noleap.nc'), resolve_data_path('${BOUNDARY_FOLDER_BAROCLINIC_CMIP6}/GFDL-ESM4/ssp126/bdy/bdy_3d_so_20150101_21001231_noleap.nc')], 'so'), on_grid=True, climatology=False)
    sim.open_boundaries.z.set(pygetm.input.from_nc([resolve_data_path('${BOUNDARY_FOLDER_BAROTROPIC_CMIP6}/GFDL-ESM4/historical/bdy/bdy_2d_20100101_20141231_noleap.nc'), resolve_data_path('${BOUNDARY_FOLDER_BAROTROPIC_CMIP6}/GFDL-ESM4/ssp126/bdy/bdy_2d_20150101_21001231_noleap.nc')], 'zos'), on_grid=True)
    sim.open_boundaries.u.set(pygetm.input.from_nc([resolve_data_path('${BOUNDARY_FOLDER_BAROTROPIC_CMIP6}/GFDL-ESM4/historical/bdy/bdy_2d_20100101_20141231_noleap.nc'), resolve_data_path('${BOUNDARY_FOLDER_BAROTROPIC_CMIP6}/GFDL-ESM4/ssp126/bdy/bdy_2d_20150101_21001231_noleap.nc')], 'uo'), on_grid=True)
    sim.open_boundaries.v.set(pygetm.input.from_nc([resolve_data_path('${BOUNDARY_FOLDER_BAROTROPIC_CMIP6}/GFDL-ESM4/historical/bdy/bdy_2d_20100101_20141231_noleap.nc'), resolve_data_path('${BOUNDARY_FOLDER_BAROTROPIC_CMIP6}/GFDL-ESM4/ssp126/bdy/bdy_2d_20150101_21001231_noleap.nc')], 'vo'), on_grid=True)
    sim['temp'].open_boundaries.type = 5
    sim['salt'].open_boundaries.type = 5
    # placeholder -- overwritten below by meteo.data_script (set_meteo_data) when radiation_source: pseudo_tcc; unused (but still required to have a real value) for net/components
    sim.airsea.tcc.set(0.5)
    sim.radiation.A.set(0.7)
    sim.radiation.kc1.set(0.54)
    sim.radiation.kc2.set(3.23)

    # river_discharge.data_script -- see generated_nse_cmip6_raw_utils.py
    set_river_data(sim, domain, config)

    # meteo.data_script -- see generated_nse_cmip6_raw_utils.py
    set_meteo_data(sim, domain, config)

    return sim

def configure_output(sim):
    # --- output ---
    output_file_2 = sim.output_manager.add_netcdf_file(
        path=pathlib.Path(resolve_data_path('${OUTPUT_FOLDER}/nse_2d.nc')),
        sync_interval=1,
        format='NETCDF4',
        interval=1,
        interval_units=pygetm.output.TimeUnit.DAYS,
        default_dtype='float32',
        save_initial=not bool(args.load_restart),
    )
    _request_output_fields(output_file_2, ['Ht', 'zt', 'Dt', 'u1', 'v1'], skip_unavailable=args.skip_unavailable_output, label='output.files[2].variable_requests[0]')
    output_file_3 = sim.output_manager.add_netcdf_file(
        path=pathlib.Path(resolve_data_path('${OUTPUT_FOLDER}/nse_3d.nc')),
        sync_interval=1,
        format='NETCDF4',
        interval=1,
        interval_units=pygetm.output.TimeUnit.MONTHS,
        default_dtype='float32',
        save_initial=not bool(args.load_restart),
    )
    _request_output_fields(output_file_3, ['temp', 'salt', 'rho', 'nuh', 'uk', 'vk', 'ww', 'SS', 'num'], skip_unavailable=args.skip_unavailable_output, label='output.files[3].variable_requests[0]', time_average=True)
    if sim.fabm:
        _request_output_fields(output_file_3, ['P1_c', 'P2_c', 'P3_c', 'P4_c', 'O2_o', 'N3_n', 'N4_n', 'N1_p', 'N5_s', 'Q6_c', 'Y2_c', 'Y3_c', 'O3_c', 'O3_fair', 'Q7_c', 'Q6_pen_depth_c', 'ben_col_D1m', 'ben_col_D2m', 'N5_s_bdy', 'N5_s_sms', 'N5_s_sfl', 'N5_s_bfl', 'N5_s_sfl_tot_calculator_result', 'N5_s_bfl_tot_calculator_result', 'N5_s_sms_tot_calculator_result'], skip_unavailable=args.skip_unavailable_output, label='output.files[3].variable_requests[1]', time_average=True)
    else:
        print('output.files[3].variable_requests[1]: skipping 25 field(s) -- sim.fabm not configured', file=sys.stderr)
    _output_file_4_start = cftime.datetime(2010, 1, 1, 0, 0, 0, 0, calendar='noleap')
    _output_file_4_stop = cftime.datetime(2020, 1, 1, 0, 0, 0, 0, calendar='noleap')
    output_file_4 = sim.output_manager.add_netcdf_file(
        path=pathlib.Path(resolve_data_path('${OUTPUT_FOLDER}/surf_bott_daily.nc')),
        sync_interval=1,
        format='NETCDF4',
        interval=1,
        interval_units=pygetm.output.TimeUnit.DAYS,
        save_initial=not bool(args.load_restart),
        start=_output_file_4_start,
        stop=_output_file_4_stop,
    )
    _request_output_fields(output_file_4, ['temp', 'salt'], skip_unavailable=args.skip_unavailable_output, label='output.files[4].variable_requests[0]', generate_unique_name=True, sim=sim, z_index=-1)
    _request_output_fields(output_file_4, ['temp', 'salt'], skip_unavailable=args.skip_unavailable_output, label='output.files[4].variable_requests[1]', generate_unique_name=True, sim=sim, z_index=0)


def run(sim):
    if args.save_restart:
        _restart_kwargs = {}
        _interval = args.save_restart_interval
        if _interval is None:
            _interval = config.get('runtime', {}).get('save_restart_interval')
        if _interval is not None:
            _restart_kwargs['interval'] = _interval
            _units_arg = args.save_restart_interval_units
            if _units_arg is None:
                _units_arg = config.get('runtime', {}).get('save_restart_interval_units', 'TIMESTEPS')
            # companion-config/baked value is TimeUnit's raw int .value (e.g. 6 for
            # MONTHS); a human typing --save-restart-interval-units on the command
            # line instead gives its NAME ('MONTHS') -- accept either form.
            _restart_kwargs['interval_units'] = (
                pygetm.output.TimeUnit(_units_arg) if isinstance(_units_arg, int)
                else getattr(pygetm.output.TimeUnit, _units_arg))
        sim.output_manager.add_restart(args.save_restart, **_restart_kwargs)

    # --- start ---
    _start_kwargs = {k: _coerce_runtime_value(v) for k, v in config.get('runtime', {}).items() if k not in ('check_finite', 'time', 'debug_output', 'post_data_script', 'calendar', 'stop', 'save_restart_interval', 'save_restart_interval_units') and v is not None}
    if args.load_restart:
        _restart_time = None
        if args.load_restart_time:
            _restart_time = datetime.datetime.fromisoformat(args.load_restart_time)
        _start_kwargs['time'] = sim.load_restart(args.load_restart, time=_restart_time)
    elif args.start:
        _start_dt = datetime.datetime.fromisoformat(args.start)
        _calendar = config.get('runtime', {}).get('calendar')
        if _calendar:
            _start_kwargs['time'] = cftime.datetime(
                _start_dt.year, _start_dt.month, _start_dt.day, _start_dt.hour,
                _start_dt.minute, _start_dt.second, _start_dt.microsecond,
                calendar=_calendar)
        else:
            _start_kwargs['time'] = _start_dt
    else:
        print('runtime.time is required (or pass --start / --load-restart)', file=sys.stderr)
        sys.exit(1)
    sim.start(**_start_kwargs)

    _dry_run = args.dry_run if args.dry_run is not None else (False and not args.stop)
    if not _dry_run and args.stop:
        _stop_dt = datetime.datetime.fromisoformat(args.stop)
        _calendar = config.get('runtime', {}).get('calendar')
        if _calendar:
            stop = cftime.datetime(
                _stop_dt.year, _stop_dt.month, _stop_dt.day, _stop_dt.hour,
                _stop_dt.minute, _stop_dt.second, _stop_dt.microsecond,
                calendar=_calendar)
        else:
            stop = _stop_dt
        while sim.time < stop:
            sim.advance(check_finite=bool(config.get('runtime', {}).get('check_finite', False)))
        sim.finish()
    elif _dry_run:
        print(f"dry run: built and started only, not advanced, time={sim.time}", file=sys.stderr)
        sim.finish()
    else:
        print("--stop is required unless --dry-run is given", file=sys.stderr)
        sys.exit(1)

def main():
    domain = create_domain()
    sim = create_simulation(domain)
    configure_output(sim)
    run(sim)

if __name__ == '__main__':
    main()
